const classicIcoHref = "data:image/svg+xml;base64,";
const defaultIcoHref = "https://images.rbxcdn.com/e854eb7b2951ac03edba9a2681032bba.ico";

function manageFaviconState() {
    observer.disconnect();

    const hasClassicTheme = document.body && document.body.classList.contains('classic-theme');
    const chosenHref = hasClassicTheme ? classicIcoHref : defaultIcoHref;

    const existingLinks = document.querySelectorAll('link[rel*="icon"], link[rel="apple-touch-icon"]');
    let matchingLinkFound = false;

    existingLinks.forEach(link => {
        if (link.href === chosenHref) {
            matchingLinkFound = true;
        } else {
            link.remove();
        }
    });

    if (!matchingLinkFound) {
        const newLink = document.createElement('link');
        newLink.href = chosenHref;
        newLink.rel = 'icon';

        const appleLink = document.createElement('link');
        appleLink.href = chosenHref;
        appleLink.rel = 'apple-touch-icon';

        if (document.head) {
            document.head.appendChild(newLink);
            document.head.appendChild(appleLink);
        } else {
            document.documentElement.appendChild(newLink);
            document.documentElement.appendChild(appleLink);
        }
    }

    startObserving();
}

function startObserving() {
    observer.observe(document.documentElement, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['href', 'rel', 'class']
    });
}

const observer = new MutationObserver(() => {
    const hasClassicTheme = document.body && document.body.classList.contains('classic-theme');
    const expectedHref = hasClassicTheme ? classicIcoHref : defaultIcoHref;
    const currentActiveLink = document.querySelector(`link[href="${expectedHref}"]`);

    if (!currentActiveLink) {
        manageFaviconState();
    }
});

manageFaviconState();